            before.discard(name)
        for after in self.name2after.values():
            after.discard(name)

def l33t_match(password, _ranked_dictionaries=RANKED_DICTIONARIES,
               _l33t_table=L33T_TABLE):
    matches = []

    for sub in enumerate_l33t_subs(
            relevant_l33t_subtable(password, _l33t_table)):
        if not sub:
            break

        subbed_password = translate(password, sub)

        for match in dictionary_match(subbed_password, _ranked_dictionaries):
            token = password[match['i']:match['j'] + 1]

            # Keep only substitutions that are actually used within
            # the matched token. This excludes direct dictionary matches
            # and substitutions occurring elsewhere in the password.
            match_sub = {
                subbed_chr: chr
                for subbed_chr, chr in sub.items()
                if subbed_chr in token and subbed_chr != chr
            }

            if not match_sub:
                continue

            match['l33t'] = True
            match['token'] = token
            match['sub'] = match_sub
            matches.append(match)

    # Exclude one-character matches, consistent with the original behavior.
    matches = [
        match for match in matches
        if len(match['token']) > 1
    ]

    return sorted(matches, key=lambda x: (x['i'], x['j']))

def l33t_match(password, _ranked_dictionaries=RANKED_DICTIONARIES,
               _l33t_table=L33T_TABLE):
    matches = []

    for sub in enumerate_l33t_subs(
            relevant_l33t_subtable(password, _l33t_table)):
        if not len(sub):
            break

        subbed_password = translate(password, sub)
        for match in dictionary_match(subbed_password, _ranked_dictionaries):
            token = password[match['i']:match['j'] + 1]

            # Exclude single-character matches.
            if len(token) <= 1:
                continue

            if token.lower() == match['matched_word']:
                # Only return matches that contain an actual substitution.
                continue

            # Subset of mappings in sub that are in use for this match.
            match_sub = {}
            for subbed_chr, chr in sub.items():
                if subbed_chr in token:
                    match_sub[subbed_chr] = chr

            match['l33t'] = True
            match['token'] = token
            match['sub'] = match_sub
            match['sub_display'] = ', '.join(
                ["%s -> %s" % (k, v) for k, v in match_sub.items()]
            )
            matches.append(match)

    return matches

